import {api,jobs} from './data.js';
const app=document.querySelector('#app'),uk=document.body.dataset.site==='ukr',admin=document.body.dataset.site==='admin';
const workers=await api.workers();
let requests=[],companyProfile=null;
const state={favorites:new Set(),wizard:0,form:{},files:{},submitted:null,messages:[],approved:new Set(),filter:{},account:null,authConfig:{},sna:null,snaBusy:false};
async function companyApi(path,options={}){const response=await fetch('/api/v1/company/'+path,{...options,headers:typeof options.body==='string'?{'Content-Type':'application/json'}:{}});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:'Controleer de ingevulde gegevens en probeer het opnieuw.');return data}
async function loadCabinet(){if(uk||admin||state.account?.company?.status!=='approved'){requests=[];state.favorites=new Set();companyProfile=null;return}try{const [data,favs,prof]=await Promise.all([companyApi('requests'),companyApi('favorites'),companyApi('profile')]);requests=data.items||[];state.favorites=new Set(favs.ids||[]);companyProfile=prof}catch(error){toast(error.message)}}
if(!uk&&!admin){[state.account,state.authConfig]=await Promise.all([companyApi('me').catch(()=>null),companyApi('auth/config').catch(()=>({}))]);await loadCabinet()}
const avatar=(w,large=false)=>`<img class="provider-avatar ${w.providerType==='company'?'company':'individual'} ${large?'large':''}" src="${new URL('./images/'+w.avatar,import.meta.url).href}" alt="${w.providerType==='company'?'Bedrijfslogo':'Portret van een vakman'}" loading="lazy"/>`;
const art=(job,cls='')=>{const names={Timmerman:'carpenter',Elektricien:'electrical',Kabelmonteur:'cable',Schilder:'finishing',Lasser:'welder',Tegelzetter:'tiler',Loodgieter:'plumber',Grondwerker:'groundworker',Betonwerker:'concrete','Allround vakman':'allround'};return names[job]?`<img class="trade-art ${cls}" src="${new URL('./images/'+names[job]+'.png',import.meta.url).href}" alt=""/>`:icon(({Lasser:'wrench',Tegelzetter:'grid-2x2',Loodgieter:'wrench',Grondwerker:'shovel',Betonwerker:'brick-wall','Allround vakman':'hammer'})[job]||'hammer')};
const photo='https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&w=1100&q=85';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nlDate=v=>{const [y,m,d]=String(v||'').split('-');return d?`${d}-${m}-${y}`:'—'};
const icon=(name)=>'<i data-lucide="'+name+'" aria-hidden="true"></i>';
const icons=()=>window.lucide?.createIcons({attrs:{'stroke-width':1.7,'aria-hidden':'true'}});
const btn=(text,href,cls='')=>`<a class="btn ${cls}" href="#${href}">${text}</a>`;
const brand=()=>`<a href="#home" class="brand">${uk?'<span class="mark">↗</span>':`<img src="./assets/logo.png" alt=""/>`}${uk?'Ukrwerkspot':'UHR'}${admin?' · Admin':''}</a>`;
const demo=()=>'';
const header=()=>`${demo()}<div class="wrap"><header class="header">${brand()}<nav class="nav">${uk?'<a href="#home/how">Як це працює</a><a href="#home/benefits">Для майстрів</a><a href="#faq">Поширені запитання</a>':'<a href="#home/benefits">Voor opdrachtgevers</a><a href="#catalog">Vakmensen</a><a href="#home/how">Hoe het werkt</a><a href="#about">Over UHR</a><a href="#contact">Contact</a>'}<select class="language" aria-label="${uk?'Мова':'Taal'}"><option>${uk?'Українська':'NL'}</option><option>EN</option>${uk?'<option>Nederlands</option>':''}</select>${uk?btn('Заповнити анкету','register'):btn(state.account?'Mijn account':'Inloggen','login','light')+btn('Bedrijf aanmelden','register')}</nav></header></div>`;
const footer=()=>`<div class="wrap"><footer class="footer">${brand()}<div class="links"><a href="#contact">${uk?'Контакти':'Contact'}</a><a href="#privacy">${uk?'Конфіденційність':'Privacybeleid'}</a><a href="#terms">${uk?'Умови використання':'Algemene voorwaarden'}</a><a href="#cookies">Cookiebeleid</a><a href="#faq">FAQ</a></div><span>© 2026 ${uk?'Ukrwerkspot':'UHR'}</span></footer></div>`;
function landing(){const benefits=uk?['Перевірені замовники','Захист особистих контактів','Пропозиції за спеціалізацією','Підтримка менеджера','Ваш досвід має значення','Без відкритої публікації даних']:['Gecontroleerde vakmensen','Geldige VCA-certificaten','Landelijke inzetbaarheid','Eén vast contactpersoon','Snelle personeelsplanning','Beschermde contactgegevens'];const steps=uk?['Заповніть анкету','Додайте документи та роботи','Ми перевіримо ваш профіль','Отримуйте пропозиції']:['Registreer uw bedrijf','Wij controleren uw gegevens','Vind de juiste vakmensen','Uw manager regelt de rest'];return `${header()}<main><div class="wrap"><section class="hero"><div><div class="eyebrow">${uk?'Українська майстерність. Нідерландські можливості.':'Ukrainian expertise. Dutch ambition.'}</div><h1>${uk?'Ваша майстерність.<br>Наші можливості.<br><span>Спільне майбутнє.</span>':'Goede mensen.<br>Sterke projecten.<br><span>Samen bouwen.</span>'}</h1><p>${uk?'Працюєте у будівельній сфері в Нідерландах? Приєднуйтесь до бази перевірених майстрів. Заповніть профіль та отримуйте пропозиції через нашого менеджера.':'Gekwalificeerde vakmensen voor de Nederlandse bouwsector. Wij verbinden uw bouwbedrijf met betrouwbare Oekraïense professionals. Met ons bouwt u meer.'}</p><div class="actions">${btn(uk?'Заповнити анкету ↗':'Bekijk beschikbare vakmensen ↗',uk?'register':'catalog')}${btn(uk?'Як це працює':'Bedrijf aanmelden',uk?'home/how':'register','light')}</div><div class="trust"><span>✓ ${uk?'Перевірка VCA':'VCA-gecontroleerd'}</span><span>✓ ${uk?'Особистий менеджер':'Eén vast contactpersoon'}</span></div></div><div class="visual"><img src="${photo}" alt="${uk?'Будівельні роботи на об’єкті':'Professionals op een bouwplaats'}"/><div class="float-card"><div><strong>${uk?'01':workers.length}</strong><small>${uk?'Анкета — перший крок':'Beschikbare vakmensen'}</small></div><div><strong>VCA ✓</strong><small>${uk?'Безпека та професійність':'Gecontroleerde certificaten'}</small></div><div><strong>NL</strong><small>${uk?'Працюємо по всій країні':'Landelijke dekking'}</small></div></div></div></section><div class="strip"><span>${uk?'Майстерність без кордонів':'Een betrouwbare partner voor uw bouwproject'}</span><span>KVK · VCA · ${uk?'Підтримка українською':'Persoonlijke begeleiding'}</span></div></div><section class="section cream" id="benefits"><div class="wrap"><div class="section-head"><div><div class="eyebrow">${uk?'Спокій та впевненість':'Waarom kiezen voor UHR'}</div><h2>${uk?'Ви працюєте. Ми підтримуємо.':'Vakmanschap waarop u kunt rekenen.'}</h2></div><p>${uk?'Більше часу для того, що ви вмієте найкраще.':'Minder zoeken. Meer zekerheid.'}</p></div><div class="grid">${benefits.map((b,i)=>`<article class="card"><div class="icon">${icon(['shield-check','lock-keyhole','map-pin','handshake','calendar-check','user-check'][i])}</div><h3>${b}</h3><p>${uk?['Ми перевіряємо компанії перед співпрацею.','Контакти доступні лише вашому менеджеру.','Ваш досвід допомагає знайти відповідний проєкт.','Поруч на кожному етапі співпраці.','Покажіть сертифікати та приклади робіт.','У каталозі — лише професійна інформація.'][i]:['Zorgvuldig beoordeeld op ervaring en expertise.','Veiligheid op de bouwplaats staat voorop.','De juiste specialist, waar uw project ook is.','Alle afstemming via uw UHR-manager.','Overzichtelijke beschikbaarheid en aanvragen.','Persoonlijke gegevens blijven vertrouwelijk.'][i]}</p></article>`).join('')}</div></div></section>${!uk?`<section class="section wrap"><div class="section-head"><div><div class="eyebrow">Onze specialisaties</div><h2>Voor elke klus de juiste vakman.</h2></div>${btn('Alle vakmensen ↗','catalog','light')}</div><div class="grid profession-grid">${jobs.map((j,i)=>`<a class="card" href="#catalog/${j}"><div class="category-art">${art(j)}</div><h3>${j} ↗</h3><span class="muted">${workers.filter(w=>w.job===j).length} profielen</span></a>`).join('')}</div></section>`:''}<section class="section wrap" id="how"><div class="eyebrow">${uk?'Лише кілька простих кроків':'Zo werkt het'}</div><h2>${uk?'Від анкети до нового проєкту.':'Van kennismaking naar samenwerking.'}</h2><div class="steps">${steps.map((s,i)=>`<div class="step"><b>0${i+1}</b><h3>${s}</h3><p>${uk?'Зрозумілий процес із підтримкою менеджера.':'Duidelijke stappen, persoonlijke begeleiding.'}</p></div>`).join('')}</div><div class="note">◇ ${uk?'Ваші особисті контакти не публікуються. Спілкування із замовниками відбувається через менеджера.':'Persoonlijke gegevens van vakmensen worden beschermd. Alle communicatie verloopt via UHR.'}</div></section><section class="wrap section"><div class="callout"><div><h2>${uk?'Зробіть наступний крок.':'Klaar om samen meer te bouwen?'}</h2><p>${uk?'Розкажіть про свій досвід — ми допоможемо знайти можливості.':'Meld uw bedrijf aan en ontdek de mogelijkheden.'}</p></div>${btn(uk?'Заповнити анкету ↗':'Bedrijf aanmelden ↗','register','lime')}</div></section></main>${footer()}`}
const menus=[['overview','◫','Overzicht'],['catalog','▦','Vakmensen'],['favorites','♡','Favorieten'],['requests','↗','Aanvragen'],['messages','◷','Berichten'],['company','⌂','Bedrijfsprofiel'],['documents','▤','Documenten'],['settings','⚙','Instellingen']];
function shell(content,page){const items=admin?[["overview","layout-dashboard","Огляд"],["masters","users","Анкети майстрів"],["companies","building-2","Компанії"],["requests","clipboard-list","Заявки"],["messages","messages-square","Повідомлення"]]:menus;const names={overview:"layout-dashboard",catalog:"users",favorites:"heart",requests:"clipboard-list",messages:"messages-square",company:"building-2",documents:"files",settings:"settings"};const link=([id,,label])=>`<a class="${page===id?"active":""}" ${page===id?'aria-current="page"':""} href="#${id}">${icon(names[id]||"users")}${label}</a>`;return `${demo()}<div class="workspace"><header class="workspace-header"><div class="workspace-nav">${brand()}<nav aria-label="Werkruimte">${items.slice(0,5).map(link).join("")}</nav><details class="account-menu"><summary>${icon("building-2")}<span>${admin?"Менеджер":"Mijn bedrijf"}</span>${icon("chevron-down")}</summary><div class="dropdown">${items.slice(5).map(link).join("")}<a href="#home" ${admin?'':'data-logout'}>${icon("log-out")}${admin?"До сайтів":"Uitloggen"}</a></div></details></div></header><main class="content"><div class="topbar"><span>${admin?"Спільна адмінка · Ukrwerkspot + UHR":"Werkruimte / "+(menus.find(x=>x[0]===page)?.[2]||"Vakmanprofiel")}</span><span>${admin?"Менеджернстрація":esc(companyProfile?.company_name||"Mijn bedrijf")+" · Geverifieerd"}</span></div>${content}</main></div>`}
const placeText=w=>esc(w.radius?`${w.region} · ${w.radius} km`:w.region);
const yearsText=w=>w.years?`${w.years} jaar ervaring`:'Ervaring op aanvraag';
const rateText=w=>w.rate?`€ ${w.rate}`:'Op aanvraag';
const certText=w=>esc(w.cert.join(' · ')||'Certificaten in controle');
function workerCard(w){return `<article class="worker-row"><div class="worker-identity">${avatar(w)}<div><span class="muted">${w.providerType==='company'?'Bedrijf':'Vakman'} #${w.id}</span><a href="#profile/${w.id}"><h3>${esc(w.job)}</h3></a><span class="provider-kind">${w.providerType==='company'?'Bouwbedrijf':'Zelfstandig vakman'}</span><span class="badge ${w.available==='Direct beschikbaar'?'':'yellow'}">${esc(w.available)}</span></div></div><div class="worker-facts"><span>${icon("map-pin")} ${placeText(w)}</span><span>${icon("clock")} ${yearsText(w)}</span><span>${icon("shield-check")} ${certText(w)}</span></div><div class="worker-price"><strong>${rateText(w)}</strong><small>${w.rate?'/ uur · excl. btw':'Tarief via uw manager'}</small></div><div class="row-actions"><button data-fav="${w.id}" class="favorite ${state.favorites.has(w.id)?"saved":""}" aria-label="Favoriet" aria-pressed="${state.favorites.has(w.id)}">${icon("heart")}</button>${btn("Bekijk profiel","profile/"+w.id,"light")}${btn("Aanvragen","request/"+w.id)}</div></article>`}
function overview(){return shell(`<div class="section-head"><div><div class="eyebrow">Uw projecten, goed geregeld</div><h1>Welkom terug${companyProfile?.contact_name?', '+esc(companyProfile.contact_name):''}.</h1><p>Alles wat u nodig heeft voor uw volgende bouwproject.</p></div>${btn('Vakmensen zoeken ↗','catalog')}</div><div class="stats">${[['Beschikbare vakmensen',workers.length,'In heel Nederland'],['Actieve aanvragen',requests.filter(x=>!['Afgerond','Geannuleerd'].includes(x.status)).length,'Uw manager houdt u op de hoogte'],['Berichten van uw manager',requests.reduce((n,r)=>n+(r.manager_messages||0),0),'In uw aanvragen'],['Favoriete vakmensen',state.favorites.size,'Uw persoonlijke selectie']].map(([a,b,c])=>`<div class="card">${a}<strong>${b}</strong>${c}</div>`).join('')}</div><div class="section-head"><h3>Recente aanvragen</h3><a href="#requests">Bekijk alles ↗</a></div>${requestTable()}<div class="section-head" style="margin-top:35px"><h3>Beschikbaar voor uw volgende project</h3>${btn('Alle vakmensen','catalog','light')}</div><div class="cards">${workers.slice(0,2).map(workerCard).join('')}</div><div class="note">Laatste activiteit · Uw bedrijfsprofiel is gecontroleerd. Uw UHR-manager staat voor u klaar.</div>`,'overview')}
function catalog(favorites=false,job=""){return shell(`<div class="section-head"><div><div class="eyebrow">Betrouwbare expertise</div><h1>${favorites?"Uw favoriete vakmensen":"Vind uw volgende vakman."}</h1><p>Gecontroleerde professionals. Alle communicatie via uw manager.</p></div><span class="catalog-view">${icon("list")} Lijstweergave</span></div><div class="catalog"><div class="filter-toolbar"><div class="search-control">${icon("search")}<input class="search" id="search" placeholder="Zoek op beroep, regio of vakman-ID…" aria-label="Zoeken"/></div><button class="btn light" data-filter-toggle aria-expanded="false" aria-controls="catalog-filters">${icon("sliders-horizontal")} Filters</button></div><div class="filters" id="catalog-filters"><div class="filter-heading"><h3>Verfijn uw selectie</h3><button data-reset class="btn light">${icon("rotate-ccw")} Wissen</button></div><div class="filter-fields">${select("Beroep","job",["Alle beroepen",...jobs],job)}${select("Locatie","region",["Heel Nederland",...new Set(workers.map(w=>w.region))])}${select("Werkstraal","radius",["Alle afstanden","50","70","100"])}<label>Max. uurtarief<input id="rate" type="number" min="1" placeholder="Bijv. 40"/></label>${select("Ervaring","years",["Alle ervaring","5","10","15"])}${select("Beschikbaarheid","available",["Alle","Direct beschikbaar"])}${select("Certificaat","cert",["Alle certificaten","VCA"])}</div><button class="btn filter-done" data-filter-toggle>Resultaten bekijken</button></div><div class="results-heading"><p id="result-count" class="muted" aria-live="polite"></p><span class="muted">Gesorteerd op relevantie</span></div><div class="cards worker-list" id="worker-results" data-favorites="${favorites}"></div></div>`,favorites?"favorites":"catalog")}
function select(label,id,opts,value=''){return `<label>${label}<select id="${id}" name="${id}">${opts.map(v=>`<option ${(value||state.form[id])===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`}
function filterCards(){const target=document.querySelector('#worker-results');if(!target)return;const val=id=>document.getElementById(id)?.value||'';const search=val('search').toLowerCase();const list=workers.filter(w=>(target.dataset.favorites!=='true'||state.favorites.has(w.id))&&`${w.job} ${w.region} ${w.id}`.toLowerCase().includes(search)&&(!jobs.includes(val('job'))||w.job===val('job'))&&(val('region')==='Heel Nederland'||w.region===val('region'))&&(!val('rate')||(w.rate&&w.rate<=Number(val('rate'))))&&(!Number(val('years'))||w.years>=Number(val('years')))&&(!Number(val('radius'))||(w.radius&&w.radius<=Number(val('radius'))))&&(val('available')!=='Direct beschikbaar'||w.available==='Direct beschikbaar')&&(val('cert')==='Alle certificaten'||w.cert.some(c=>c.includes(val('cert')))));target.innerHTML=list.map(workerCard).join('')||'<div class="card empty">Geen vakmensen gevonden. Pas uw filters aan.</div>';icons();document.querySelector('#result-count').textContent=`${list.length} vakmensen gevonden`;}
function profile(id){const w=workers.find(w=>w.id===Number(id));if(!w)return info("404");return shell(`<a href="#catalog" class="back-link">${icon("arrow-left")} Terug naar vakmensen</a><section class="profile-hero"><div><div class="eyebrow">Vakman #${w.id} · Gecontroleerd door UHR</div><h1>Vakmanschap voor<br>uw volgende project.</h1><h2>${esc(w.job)} in ${esc(w.region)}</h2><p>${esc(w.works||'Zorgvuldig werk, heldere planning en aandacht voor veiligheid.')}</p><div class="actions">${btn("Aanvraag indienen","request/"+w.id,"lime")}<button class="btn light favorite ${state.favorites.has(w.id)?"saved":""}" data-fav="${w.id}" aria-label="Favoriet" aria-pressed="${state.favorites.has(w.id)}">${icon("heart")} Bewaren</button></div></div><div class="profile-seal">${avatar(w,true)}<strong>${w.providerType==='company'?'Bedrijf':'Vakman'} #${w.id}</strong><span>${w.providerType==='company'?'Bouwbedrijf':'Zelfstandig vakman'}</span><span class="badge">${esc(w.available)}</span></div></section><div class="profile-metrics"><div><strong>${w.years?w.years+' jaar':'—'}</strong><span>Werkervaring</span></div><div><strong>${esc(w.region)}</strong><span>${w.radius?'Werkstraal '+w.radius+' km':'Werkgebied'}</span></div><div><strong>${w.rate?'€ '+w.rate+' / uur':'Op aanvraag'}</strong><span>${w.rate?'Exclusief btw':'Tarief via uw manager'}</span></div><div><strong>${certText(w)}</strong><span>Certificaten</span></div></div><nav class="profile-nav"><a href="#profile/${w.id}" data-section="expertise">Expertise</a><a href="#profile/${w.id}" data-section="work">Uitgevoerde werken</a><a href="#profile/${w.id}" data-section="contact">Contact & aanvragen</a></nav><section class="profile-section" id="expertise"><div><div class="eyebrow">Ervaring & expertise</div><h2>Een betrouwbare specialist<br>op uw bouwplaats.</h2></div><div><p>${esc(w.description||`Ervaren ${w.job.toLowerCase()}. Stemt de uitvoering zorgvuldig af via de UHR-manager.`)}</p><h3>Certificaten</h3>${w.cert.map(c=>`<span class="badge">${icon("shield-check")} ${esc(c)}</span> `).join("")||'<p class="muted">Certificaten worden gecontroleerd door UHR.</p>'}</div></section><section class="profile-section work-section" id="work"><div><div class="eyebrow">Uitgevoerde werken</div><h2>Aandacht voor het detail.</h2><p>Illustratieve voorbeelden; geen werkelijk portfolio van deze vakman.</p></div><div class="work-stories">${["Renovatie van een woonproject","Uitvoering op een bouwlocatie"].map((title,i)=>`<article class="work-story"><img src="${photo}" alt="Illustratieve bouwfoto" loading="lazy"/><div><span class="muted">${i?"Nieuwbouw":"Renovatie"}</span><h3>${title}</h3><p>Voorbereiding, vakkundige uitvoering en zorgvuldige oplevering. Projectinformatie zonder persoonlijke gegevens.</p></div></article>`).join("")}</div></section><section class="profile-contact" id="contact"><div><div class="eyebrow">${icon("lock-keyhole")} Beschermde contactgegevens</div><h2>Deze vakman op uw project?</h2><p>Contactgegevens zijn beschermd. Na uw aanvraag neemt uw UHR-contactpersoon contact met u op.</p></div>${btn("Aanvraag indienen","request/"+w.id)}</section>` ,"catalog")}
function requestTable(){if(!requests.length)return '<div class="card empty">Nog geen aanvragen. Kies een vakman en dien een aanvraag in.</div>';return `<div class="card table-scroll"><table><thead><tr>${['Aanvraag','Project','Specialisatie','Startdatum','Status','Manager'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${requests.map(r=>`<tr><td><a href="#request-detail/${r.id}">${esc(r.id)} ↗</a></td><td>${esc(r.project)}</td><td>${esc(r.job)}</td><td>${esc(nlDate(r.date))}</td><td><span class="badge ${r.status==='In behandeling'?'yellow':''}">${esc(r.status)}</span></td><td>UHR-manager</td></tr>`).join('')}</tbody></table></div>`}
function requestsPage(){return shell(`<h1>${admin?'Заявки компаній':'Uw aanvragen'}</h1><p>Concept → Ingediend → In behandeling → Kandidaat geselecteerd → Bevestigd → Afgerond / Geannuleerd</p><select id="request-status" style="max-width:260px;margin-bottom:20px"><option>Alle statussen</option>${['Concept','Ingediend','In behandeling','Kandidaat geselecteerd','Bevestigd','Afgerond','Geannuleerd'].map(s=>`<option>${s}</option>`).join('')}</select>${requestTable()}`,'requests')}
const field=(name,label,type='text',required=true,value)=>`<label><span>${label}${required?' *':''}</span><input name="${name}" type="${type}" ${required?'required':''} value="${esc(value??state.form[name])}"/></label>`;
const area=(name,label,required=false,value)=>`<label class="full"><span>${label}${required?' *':''}</span><textarea name="${name}" ${required?'required':''}>${esc(value??state.form[name])}</textarea></label>`;
const upload=(name,label,required=false,multiple=true)=>`<label class="upload full" data-drop><span>↑ ${label}${required?' *':''}</span><input name="${name}" type="file" accept="image/*,.pdf" ${multiple?'multiple':''} ${required&&!state.files[name]?.length?'required':''}/><small class="muted">PDF, JPG, PNG · ${uk?'до 10 MB на файл':'max. 10 MB per bestand'}</small><div data-files>${esc(state.form[name]||'')}</div></label>`;
const optional=(label,name,opts)=>select(label,name,['—',...opts]);
const NUMERIC=['radius_km','hourly_rate','expected_count'];
const CRAFTSMAN_KEYS=['name','phone','email','profession','works','experience_ua','experience_nl','city','radius_km','hourly_rate','availability','nationwide','company_name','kvk','btw','address','website','instagram','facebook','tiktok','extra_work','description','language','portfolio_url'];
const COMPANY_KEYS=['company_name','kvk','address','contact_name','contact_role','phone','website','description'];
const FORM_LABELS=uk?{name:'ПІБ',phone:'Телефон',email:'Email',profession:'Вид діяльності',works:'Перелік робіт',experience_ua:'Досвід в Україні',experience_nl:'Досвід у Нідерландах',city:'Місто',radius_km:'Радіус, км',hourly_rate:'Ставка €/год',availability:'Доступність',nationwide:'По всій території Нідерландів',company_name:'Компанія',kvk:'KVK',btw:'BTW',address:'Адреса',website:'Сайт',instagram:'Instagram',facebook:'Facebook',tiktok:'TikTok',extra_work:'Додаткові види робіт',description:'Опис досвіду',language:'Мова спілкування',portfolio_url:'Портфоліо',vca:'VCA',portfolio:'Фото робіт',tools:'Фото інструментів',vehicle:'Фото авто',certificates:'Інші сертифікати',portrait:'Фото в робочому одязі'}:{company_name:'Bedrijf',kvk:'KVK',btw:'BTW',address:'Adres',website:'Website',description:'Opmerking',contact_name:'Contactpersoon',contact_role:'Functie',email:'E-mail',phone:'Telefoon',region:'Werkgebied',desired_profession:'Specialisatie',expected_count:'Aantal vakmensen',sna:'SNA-certificaat',company_docs:'Bedrijfsdocumenten',certificates:'Certificaten'};
function applicationPayload(){const out={};for(const k of uk?CRAFTSMAN_KEYS:COMPANY_KEYS){let v=state.form[k];if(v===undefined||v===''||v==='—')continue;if(NUMERIC.includes(k))v=Number(v);out[k]=v}return out}
async function shrinkImage(file){if(!file.type.startsWith('image/')||file.type==='image/heic'||file.size<1.5*1024*1024)return file;try{const bitmap=await createImageBitmap(file);const scale=Math.min(1,2000/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.85));return blob?new File([blob],file.name.replace(/\.\w+$/,'')+'.jpg',{type:'image/jpeg'}):file}catch{return file}}
async function submitApplication(){const body=new FormData();body.append('data',JSON.stringify(applicationPayload()));let total=0;for(const [kind,files] of Object.entries(state.files))for(const original of files){const file=await shrinkImage(original);total+=file.size;body.append(kind,file,file.name)}if(total>28*1024*1024)throw new Error(uk?'Файли занадто великі разом. Залиште менше фото.':'De bestanden zijn samen te groot. Voeg minder bestanden toe.');const response=await fetch('/api/v1/public/applications/'+(uk?'craftsmen':'companies'),{method:'POST',body});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:(uk?'Не вдалося надіслати анкету. Спробуйте ще раз.':'Verzenden is niet gelukt. Probeer het opnieuw.'));return data}
function registration(){if(!uk)return companyRegistration();if(state.submitted)return `${header()}<div class="wizard card empty"><div class="icon" style="margin:auto">✓</div><h1>${uk?'Дякуємо! Ваш профіль надіслано на перевірку.':'Uw registratie wordt gecontroleerd.'}</h1><p>${uk?`Анкета № ${esc(state.submitted.id)}. Очікуваний строк перевірки: 2–3 робочі дні. Ми надіслали підтвердження з вашими даними на ${esc(state.form.email)}.`:`Aanvraag #${esc(state.submitted.id)}. Verwachte beoordeling: 2–3 werkdagen. Uw manager neemt contact met u op.`}</p>${btn(uk?'На головну':'Terug naar home','home')}</div>${footer()}`;/* Повна анкета Ukrwerkspot (вимкнена, замість неї коротка нижче):
const names=uk?['Особисті дані','Компанія','Професія','Документи','Перевірка']:['Bedrijf','Contactpersoon','Inzet & documenten','Controle'];
if(uk){if(i===0)body=field('name','Ім’я та прізвище')+field('phone','Телефон','tel')+field('email','Email','email')+select('Мова спілкування','language',['Українська','Nederlands','English'])+upload('portrait','Фото в робочому одязі');if(i===1)body=field('company','Назва компанії')+field('kvk','Номер KVK (8 цифр)')+field('btw','Номер BTW')+field('address','Адреса реєстрації KVK')+field('website','Сайт','url',false)+field('instagram','Instagram','url',false)+field('facebook','Facebook','url',false)+field('tiktok','TikTok','url',false);if(i===2)body=select('Основна спеціалізація','profession',jobs)+field('extra','Додаткові види робіт','text',false)+field('experience','Досвід роботи, років','number')+field('hourly','Ставка €/год','number')+field('city','Місто')+field('radius','Радіус роботи, км','number')+select('Доступність','availability',['Можу почати зараз','Через 2 тижні','Через місяць'])+`<label class="check"><input type="checkbox" name="nationwide" ${state.form.nationwide?'checked':''}/>Можу працювати по всій території Нідерландів</label>`+area('description','Короткий опис досвіду');if(i===3)body=upload('vca','Обов’язковий сертифікат VCA',true)+upload('certificates','Інші сертифікати')+upload('vehicle','Фото робочого автомобіля')+upload('portfolio','Фото виконаних робіт')+field('portfolio_url','Посилання на портфоліо','url',false);}
*/
const names=uk?['Про вас','Фото та VCA','Додатково','Перевірка']:['Bedrijf','Contactpersoon','Inzet & documenten','Controle'];let body='';const i=state.wizard;if(uk){if(i===0)body=field('name','Прізвище, ім’я та по батькові')+field('phone','Телефон','tel')+field('email','Email','email')+select('Вид діяльності','profession',jobs)+area('works','Перелік робіт',true)+field('experience_ua','Досвід роботи в Україні')+field('experience_nl','Досвід роботи в Нідерландах');if(i===1)body=upload('vca','Сертифікат VCA',true)+upload('portfolio','Фото виконаних робіт')+upload('tools','Фото інструментів')+upload('vehicle','Фото робочого автомобіля');if(i===2)body=`<p class="full muted">Усі поля на цьому кроці необов’язкові. Чим більше ви розкажете, тим швидше менеджер підбере для вас проєкт.</p>`+field('city','Місто','text',false)+field('radius_km','Радіус роботи, км','number',false)+field('hourly_rate','Ставка €/год','number',false)+optional('Доступність','availability',['Можу почати зараз','Через 2 тижні','Через місяць'])+optional('Мова спілкування','language',['Українська','Nederlands','English'])+`<label class="check full"><input type="checkbox" name="nationwide" ${state.form.nationwide?'checked':''}/>Можу працювати по всій території Нідерландів</label>`+field('company_name','Назва компанії','text',false)+field('kvk','Номер KVK (8 цифр)','text',false)+field('btw','Номер BTW','text',false)+field('address','Адреса реєстрації KVK','text',false)+field('website','Сайт','text',false)+field('instagram','Instagram','text',false)+field('facebook','Facebook','text',false)+field('tiktok','TikTok','text',false)+field('portfolio_url','Посилання на портфоліо','text',false)+field('extra_work','Додаткові види робіт','text',false)+area('description','Короткий опис досвіду')+upload('certificates','Інші сертифікати')+upload('portrait','Фото в робочому одязі');}/* Vorige bedrijfsaanmelding (vervangen door companyRegistration):
else{if(i===0)body=field('company_name','Bedrijfsnaam')+field('kvk','KVK-nummer (8 cijfers)')+field('btw','BTW-nummer')+field('address','Vestigingsadres')+field('website','Website','text',false)+area('description','Korte beschrijving van uw bedrijf');if(i===1)body=field('contact_name','Contactpersoon')+field('contact_role','Functie')+field('email','Zakelijk e-mailadres','email')+field('phone','Telefoonnummer','tel');if(i===2)body=field('region','Werkgebied')+select('Gewenste specialisatie','desired_profession',jobs)+field('expected_count','Verwacht aantal vakmensen','number')+select('SNA-certificering','sna',['Ja','Nee','In aanvraag'])+upload('company_docs','Bedrijfsdocumenten',true)+upload('certificates','Certificaten');}
*/if(i===names.length-1)body=`<div class="full"><h3>${uk?'Перевірте свій профіль':'Controleer uw registratie'}</h3>${Object.entries(state.form).filter(([k,v])=>FORM_LABELS[k]&&v!==''&&v!=='—'&&v!==false).map(([k,v])=>`<p><b>${esc(FORM_LABELS[k])}:</b> ${esc(v===true?(uk?'Так':'Ja'):v)}</p>`).join('')}<div class="note">${uk?'Клієнтам будуть доступні: спеціалізація, досвід, регіон, ставка, сертифікати та обезличені роботи. Особисті контакти захищені.':'Uw bedrijfsgegevens worden gecontroleerd door UHR. De gegevens van vakmensen blijven beschermd.'}</div><label class="check"><input name="consent" type="checkbox" required/>${uk?'Погоджуюся на обробку персональних даних':'Ik ga akkoord met de verwerking van mijn gegevens'} · <a href="#privacy">Privacy</a></label></div>`;return `${header()}<main class="wizard"><div class="eyebrow">${uk?'Ваш шлях до нових можливостей':'Uw eerste stap naar samenwerking'}</div><h1>${uk?'Професійний профіль':'Meld uw bedrijf aan.'}</h1><p>${uk?'Розкажіть про себе. Решту організуємо разом.':'Een zorgvuldig proces. Eén betrouwbare partner.'}</p><div class="progress">${names.map((n,j)=>`<div class="${j<=i?'active':''}">${j+1}. ${n}</div>`).join('')}</div><form id="wizard" class="card" data-last="${i===names.length-1}"><h3>${names[i]}</h3><div class="fields">${body}</div><div class="note">${uk?'Платіжні реквізити можна буде безпечно додати пізніше — після першої фактури.':'KVK: uw 8-cijferige inschrijving. BTW: uw omzetbelastingnummer. '}</div><div class="actions"><button type="button" data-back class="btn light">← ${uk?'Назад':'Terug'}</button><button class="btn">${i===names.length-1?(uk?'Надіслати на перевірку':'Registratie indienen'):(uk?'Продовжити →':'Volgende stap →')}</button></div></form></main>${footer()}`}
const googleButton=()=>state.authConfig?.google?`<div class="full"><a class="btn light" href="/api/v1/company/auth/google/start">Doorgaan met Google</a><p class="muted">of met uw e-mailadres en wachtwoord</p></div>`:'';
function companyStatus(){const c=state.account.company;const [title,text]={pending:['Uw registratie wordt gecontroleerd.',`Wij controleren uw bedrijfsgegevens en het SNA-certificaat. Na goedkeuring door uw manager ontvangt u een e-mail op ${esc(state.account.email)}.`],approved:['Uw bedrijf is goedgekeurd.','U heeft nu toegang tot gecontroleerde vakmensen.'],clarification:['Aanvullende informatie nodig.',esc(c.admin_comment||'Uw manager neemt contact met u op.')],rejected:['Registratie niet goedgekeurd.',esc(c.admin_comment||'Neem contact op met UHR voor meer informatie.')]}[c.status]||['Uw registratie is ontvangen.',''];return `${header()}<div class="wizard card empty"><div class="icon" style="margin:auto">${['pending','approved'].includes(c.status)?'✓':'!'}</div><h1>${title}</h1><p>${esc(c.company_name)} · aanmelding #${esc(c.id)}</p><p>${text}</p>${c.status==='approved'?btn('Naar de werkruimte','overview'):btn('Terug naar home','home')}</div>${footer()}`}
function snaNote(){if(state.snaBusy)return '<div class="note full">Het certificaat wordt gelezen en gecontroleerd in het SNA-register…</div>';const s=state.sna;if(!s)return '';const r=s.register;let text;if(s.verified)text=`<b>✓ Gevonden in het SNA-register</b><br>${esc(r.company_name)} · ${esc(r.address)} · KvK ${esc(s.kvk)}${r.activities?.length?'<br>'+r.activities.map(esc).join(' · '):''}`;else if(!s.kvk)text='Wij konden het KVK-nummer niet uit het bestand lezen. Vul het hieronder in en controleer opnieuw.';else if(!s.kvk_matches)text=`Het KVK-nummer op het certificaat (${esc(s.extracted.kvk)}) komt niet overeen met ${esc(s.kvk)}. Controleer het nummer.`;else if(r?.found)text=`<b>${esc(r.company_name)} staat in het SNA-register.</b><br>Het certificaat zelf kon niet automatisch worden gelezen; uw manager controleert het handmatig.`;else if(r?.found===false)text=`KVK-nummer ${esc(s.kvk)} staat niet in het SNA-register. U kunt doorgaan; uw manager controleert het certificaat handmatig.`;else text='Het SNA-register kon niet automatisch worden geraadpleegd. U kunt doorgaan; uw manager controleert het certificaat handmatig.';return `<div class="note full">${text}</div>`}
async function checkSna(){const file=state.files.sna?.[0];if(!file)throw new Error('Voeg het SNA-certificaat toe.');const body=new FormData();const upload=await shrinkImage(file);body.append('file',upload,upload.name);body.append('kvk',state.form.kvk||'');state.snaBusy=true;try{state.sna=await companyApi('sna/check',{method:'POST',body})}finally{state.snaBusy=false}const found=state.sna.register?.found?state.sna.register:{},read=state.sna.extracted||{};state.form.kvk=state.sna.kvk||'';state.form.company_name=found.company_name||read.company_name||state.form.company_name||'';state.form.address=found.address||state.form.address||''}
function companyRegistration(){if(state.account?.company)return companyStatus();const names=['Account','SNA-certificaat','Contactgegevens','Controle'];const i=state.wizard=state.account?Math.max(1,state.wizard):0;let body='',note='';if(i===0){body=googleButton()+field('email','Zakelijk e-mailadres','email')+field('password','Wachtwoord (min. 8 tekens)','password')+field('password_repeat','Herhaal wachtwoord','password')+'<p class="full muted">Heeft u al een account? <a href="#login">Inloggen</a></p>';note='Met dit account volgt u uw aanmelding en logt u na goedkeuring in op uw werkruimte.'}if(i===1){body=upload('sna','SNA-certificaat (PDF uit het SNA-register)',true,false)+snaNote()+(state.sna?field('company_name','Bedrijfsnaam')+field('kvk','KVK-nummer (8 cijfers)')+field('address','Vestigingsadres','text',false):'');note='Download uw verklaring in het SNA-register (normeringarbeid.nl) en upload de PDF. Wij lezen het KVK-nummer uit en controleren de registratie.'}if(i===2)body=field('contact_name','Contactpersoon')+field('contact_role','Functie','text',false)+field('phone','Telefoonnummer','tel')+field('website','Website','text',false)+area('description','Opmerking')+`<p class="full muted">E-mail: ${esc(state.account.email)}</p>`;if(i===3)body=`<div class="full"><h3>Controleer uw registratie</h3>${COMPANY_KEYS.filter(k=>state.form[k]).map(k=>`<p><b>${esc(FORM_LABELS[k])}:</b> ${esc(state.form[k])}</p>`).join('')}<p><b>E-mail:</b> ${esc(state.account.email)}</p><p><b>SNA-certificaat:</b> ${esc(state.form.sna||'')} · ${state.sna?.verified?'gevonden in het SNA-register':'wordt handmatig gecontroleerd'}</p><div class="note">Na goedkeuring door uw manager ontvangt u een e-mail en krijgt u toegang tot de werkruimte.</div><label class="check"><input name="consent" type="checkbox" required/>Ik ga akkoord met de verwerking van mijn gegevens · <a href="#privacy">Privacy</a></label></div>`;const submit=i===0?'Account aanmaken →':i===1&&!state.sna?'Certificaat controleren':i===3?'Registratie indienen':'Volgende stap →';return `${header()}<main class="wizard"><div class="eyebrow">Uw eerste stap naar samenwerking</div><h1>Meld uw bedrijf aan.</h1><p>Een zorgvuldig proces. Eén betrouwbare partner.</p><div class="progress">${names.map((n,j)=>`<div class="${j<=i?'active':''}">${j+1}. ${n}</div>`).join('')}</div><form id="wizard" class="card" data-step="${i}"><h3>${names[i]}</h3><div class="fields">${body}</div>${note?`<div class="note">${note}</div>`:''}<div class="actions">${i>1?'<button type="button" data-back class="btn light">← Terug</button>':'<span></span>'}<button class="btn" data-label="${submit}">${submit}</button></div></form></main>${footer()}`}
async function companyStep(f){const i=state.wizard,button=f.querySelector('button:not([type="button"])');const busy=text=>{button.disabled=true;button.textContent=text};try{if(i===0){const data=new FormData(f);if(data.get('password')!==data.get('password_repeat'))throw new Error('De wachtwoorden komen niet overeen.');busy('Account aanmaken…');state.form.email=data.get('email');state.account=await companyApi('auth/register',{method:'POST',body:JSON.stringify({email:data.get('email'),password:data.get('password')})});state.wizard=1;render();return}saveForm(f);if(i===1&&(!state.sna||state.sna.kvk!==state.form.kvk)){busy('Certificaat controleren…');await checkSna();render();return}if(i<3){state.wizard++;render();return}busy('Bezig met verzenden…');const body=new FormData();const file=await shrinkImage(state.files.sna[0]);body.append('data',JSON.stringify(applicationPayload()));body.append('sna',file,file.name);await companyApi('registration',{method:'POST',body});state.account=await companyApi('me');state.sna=null;state.files={};render()}catch(error){toast(error.message);button.disabled=false;button.textContent=button.dataset.label}}
function requestForm(id){const w=workers.find(x=>x.id===Number(id));if(!w)return info('404');return shell(`<h1>Aanvraag indienen</h1><p>Vakman #${w.id} · ${esc(w.job)} · ${w.rate?'€ '+w.rate+'/uur':'Tarief op aanvraag'}</p><form id="request-form" class="card"><div class="fields">${field('project','Project / object','text',true,'')+field('site_address','Adres van de bouwlocatie','text',false,'')+field('start','Startdatum','date',false,'')+field('duration','Verwachte duur','text',false,'')+field('schedule','Werkschema','text',false,'')+field('count','Aantal vakmensen','number',false,'')+area('work','Beschrijving van de werkzaamheden',false,'')+area('requirements','Aanvullende eisen',false,'')}</div><div class="note">Uw aanvraag gaat naar uw UHR-manager. De contactgegevens van de vakman blijven afgeschermd.</div><button class="btn" data-worker="${w.id}">Aanvraag versturen ↗</button></form>`,'requests')}
function requestDetail(id){const r=requests.find(x=>x.id===id);if(!r)return info('404');const rows=[['Adres',r.site_address],['Duur',r.duration],['Schema',r.schedule],['Aantal vakmensen',r.workers_count],['Werkzaamheden',r.work_description],['Eisen',r.requirements]].filter(([,v])=>v);return shell(`<h1>Aanvraag ${esc(r.id)}</h1><div class="card"><h3>${esc(r.project)}</h3><p>${esc(r.job||'Specialisatie volgt')} · ${esc(nlDate(r.date))}</p><span class="badge ${r.status==='In behandeling'?'yellow':''}">${esc(r.status)}</span>${rows.map(([k,v])=>`<p><b>${k}:</b> ${esc(v)}</p>`).join('')}<div class="note">Uw UHR-manager verzorgt de afstemming.</div><div class="actions">${btn('Bericht aan manager','messages/'+r.id)}${r.worker?btn('Vakmanprofiel','profile/'+r.worker,'light'):''}</div></div>`,'requests')}
function messages(arg){if(!requests.length)return shell(`<h1>Uw UHR-contactpersoon</h1><p>Alle communicatie verloopt via UHR.</p><div class="card empty">U heeft nog geen aanvragen. Zodra u een vakman aanvraagt, kunt u hier met uw manager overleggen.</div>`,'messages');const current=requests.find(r=>r.id===arg)||requests[0];const list=requests.map(r=>`<a href="#messages/${esc(r.id)}"><strong>${esc(r.project)}</strong><br><span class="muted">${esc(r.id)} · ${esc(r.status)}</span><p>${esc(r.last_message||'Nog geen berichten')}</p></a>`).join('');const bubbles=(current.messages||[]).map(m=>`<div class="bubble ${m.sender_role==='company'?'mine':''}">${esc(m.body)}</div>`).join('')||'<p class="muted">Nog geen berichten. Stel uw vraag aan uw UHR-manager.</p>';return shell(`<h1>Uw UHR-contactpersoon</h1><p>Alle communicatie verloopt via UHR.</p><div class="chat"><aside class="card">${list}</aside><div class="card"><h3>${esc(current.project)}</h3><div class="note">${esc(current.id)} · ${esc(current.job||'Specialisatie volgt')} · ${esc(current.status)}</div>${bubbles}<form id="chat-form" data-request="${esc(current.id)}" class="actions"><input name="message" aria-label="Bericht" placeholder="Schrijf een bericht…" required style="flex:1"/><button class="btn">Versturen →</button></form></div></div>`,'messages')}
function account(page){const p=companyProfile||{},docs=page==='documents',settingsPage=page==='settings';const docRows=(p.documents||[]).map(d=>`<tr><td>${esc(d.kind_label)}</td><td>${esc(d.original_name)}</td><td><a class="btn light" href="${esc(d.url)}" target="_blank" rel="noopener">Bekijken</a></td></tr>`).join('')||'<tr><td colspan="3">Nog geen documenten.</td></tr>';const body=docs?`<div class="card table-scroll"><table><tr><th>Soort</th><th>Bestand</th><th></th></tr>${docRows}</table></div>`:settingsPage?`<div class="card"><h3>Instellingen</h3><p>De werkruimte is Nederlandstalig. Berichten van uw manager staan bij Berichten, en de goedkeuring van uw registratie komt per e-mail.</p></div>`:`<form id="account-form" class="card"><div class="fields">${field('contact_name','Contactpersoon','text',true,p.contact_name)+field('contact_role','Functie','text',false,p.contact_role)+field('phone','Telefoonnummer','tel',true,p.phone)+field('website','Website','text',false,p.website)+field('address','Vestigingsadres','text',false,p.address)+area('description','Opmerking',false,p.description)}</div><p class="muted">Bedrijf: ${esc(p.company_name)} · KVK ${esc(p.kvk)} · ${esc(p.email)}. Naam en KVK komen uit uw SNA-certificaat.</p><button class="btn" style="margin-top:25px">Wijzigingen opslaan</button></form>`;return shell(`<h1>${docs?'Uw documenten':settingsPage?'Instellingen':'Bedrijfsprofiel'}</h1><p>${esc(p.company_name||'')} · Geverifieerd${p.sna_verified?' · SNA':''}</p>${body}`,page)}
function login(reset=false,token=''){const approved=state.account?.company?.status==='approved';if(state.account&&!reset)return `${header()}<div class="wizard"><div class="card"><div class="eyebrow">Uw UHR-werkruimte</div><h1>U bent ingelogd.</h1><p>${esc(state.account.email)}</p><div class="actions">${btn(approved?'Naar de werkruimte':'Mijn aanmelding',approved?'overview':'register')}<button type="button" class="btn light" data-logout>Uitloggen</button></div></div></div>${footer()}`;const mode=token?'password':reset?'email':'';return `${header()}<div class="wizard"><div class="card"><div class="eyebrow">Uw UHR-werkruimte</div><h1>${reset?'Wachtwoord herstellen':'Welkom terug.'}</h1><p>${mode==='password'?'Kies een nieuw wachtwoord voor uw account.':mode==='email'?'Vul het e-mailadres van uw account in. Als het bij ons bekend is, sturen wij een herstellink.':'Log in om uw werkruimte te openen.'}</p><form id="login-form" data-reset="${mode}" data-token="${esc(token)}"><div class="fields">${mode?'':googleButton()}${mode==='password'?'':field('login_email','Zakelijk e-mailadres','email')}${mode==='email'?'':field('password',mode==='password'?'Nieuw wachtwoord':'Wachtwoord','password',true,'')}${mode==='password'?field('password_repeat','Herhaal wachtwoord','password',true,''):''}</div><button class="btn" style="margin:25px 0">${mode==='email'?'Herstellink aanvragen':mode==='password'?'Wachtwoord opslaan':'Inloggen →'}</button></form><a href="#${reset?'login':'reset'}">${reset?'Terug naar inloggen':'Wachtwoord vergeten?'}</a></div></div>${footer()}`}
const faqUk=['Хто може зареєструватися?','Чи потрібна реєстрація KVK?','Чи обов’язковий VCA?','Хто побачить мої особисті дані?','Як я отримуватиму пропозиції?','Чи потрібно оплачувати реєстрацію?'];
function info(page){const titles={about:'Over UHR',contact:uk?'Зв’яжіться з нами':'Contact met UHR',privacy:uk?'Конфіденційність':'Privacybeleid',terms:uk?'Умови використання':'Algemene voorwaarden',cookies:'Cookiebeleid',faq:uk?'Поширені запитання':'Veelgestelde vragen',pending:'Uw registratie wordt gecontroleerd.',rejected:'Aanvullende documenten nodig','404':uk?'Сторінку не знайдено':'Deze pagina bestaat niet.'};let body='';if(page==='faq')body=(uk?faqUk:['Wie kan zich aanmelden?','Hoe worden vakmensen gecontroleerd?','Zijn VCA-certificaten verplicht?','Kan ik direct contact opnemen met een vakman?','Hoe dien ik een aanvraag in?','Hoe wordt mijn bedrijf gecontroleerd?']).map((q,i)=>`<details><summary>${q}</summary><p>${uk?['Українські майстри та невеликі будівельні компанії, що працюють у Нідерландах.','В анкеті передбачено перевірку KVK менеджером.','Так, анкета містить обов’язкове завантаження VCA.','Менеджер бачить повну анкету. Компаніям доступний лише обезличений профіль.','Усі пропозиції та узгодження проходять через менеджера.','У прототипі оплата відсутня. Умови реєстрації будуть визначені перед запуском.'][i]:['Nederlandse bouwbedrijven kunnen zich aanmelden.','Een manager beoordeelt ervaring, documenten en beschikbaarheid.','VCA maakt deel uit van de controle.','Alle communicatie verloopt via uw UHR-manager.','Kies een vakman en vul de projectgegevens in.','UHR beoordeelt de bedrijfsgegevens en documenten handmatig.'][i]}</p></details>`).join('');else if(page==='contact')body=`<p>${uk?'Залиште повідомлення для менеджера.':'Vertel ons over uw personeelsvraag.'}</p><form id="contact-form"><div class="fields">${field('contact_name',uk?'Ваше ім’я':'Naam')+field('contact_email','Email','email')+area('message',uk?'Повідомлення':'Uw bericht')}</div><button class="btn" style="margin-top:20px">${uk?'Надіслати':'Versturen'}</button></form>`;else if(page==='about')body='<p>UHR — Ukrainian Human Resources — verbindt Nederlandse bouwbedrijven met ervaren Oekraïense vakmensen. Een vaste manager begeleidt de controle, aanvragen en projectafstemming.</p><div class="note">Vakmensen melden zich aan via Ukrwerkspot. Na beoordeling wordt uitsluitend hun professionele, geanonimiseerde profiel zichtbaar in UHR.</div>'+btn('Bedrijf aanmelden','register');else if(page==='pending'||page==='rejected')body=`<p>${page==='pending'?'Uw gegevens worden beoordeeld. In de echte omgeving ontvangt u bericht zodra de controle is afgerond.':'Het bedrijfsdocument is niet volledig leesbaar. Voeg een duidelijk document toe voor een nieuwe beoordeling.'}</p>${page==='rejected'?upload('replacement','Document bijwerken')+`<button class="btn" data-toast="Document lokaal geselecteerd. Geen gegevens verzonden.">Opnieuw indienen</button>`:btn('Terug naar home','home')}`;else if(page==='404')body=btn(uk?'На головну':'Terug naar home','home');else body=`<div class="note">${uk?'Остаточний юридичний текст буде додано до запуску.':'Voorbeeldpagina. De definitieve juridische tekst wordt vóór de livegang toegevoegd.'}</div><h3>${uk?'Обробка даних':'Gegevens en gebruik'}</h3><p>${uk?'Цей прототип не надсилає форми, не створює облікові записи та не обробляє платежі. Введені дані існують лише в пам’яті поточного перегляду.':'Dit prototype verzendt geen formulieren, maakt geen accounts aan en verwerkt geen betalingen. Ingevoerde gegevens bestaan uitsluitend in het geheugen van deze sessie.'}</p><p>${uk?'Зовнішні зображення та шрифт можуть завантажуватися зі сторонніх сервісів.':'Afbeeldingen en lettertypen kunnen van externe diensten worden geladen.'}</p>`;return `${header()}<main class="legal"><h1>${titles[page]||titles['404']}</h1>${body}</main>${footer()}`}
function adminPage(page){if(page==='requests')return requestsPage();if(page==='messages')return messages();const master=page==='masters',company=page==='companies';return shell(`<div class="eyebrow">Єдина екосистема · два домени</div><h1>${master?'Перевірка майстрів':company?'Перевірка компаній':'Центр управління UHR'}</h1><p>Ukrwerkspot → перевірка менеджером → обезличений каталог UHR → заявка компанії.</p>${!master&&!company?`<div class="stats">${[['Нові анкети','8'],['Компанії на перевірці','3'],['Активні заявки',requests.length],['Опубліковані профілі','48']].map(([a,b])=>`<div class="card">${a}<strong>${b}</strong>Overzicht</div>`).join('')}</div><div class="grid"><a class="card" href="#masters"><h3>Анкети Ukrwerkspot ↗</h3><p>Перевірка VCA та професійного досвіду.</p></a><a class="card" href="#companies"><h3>Компанії UHR ↗</h3><p>Перевірка юридичних даних та документів.</p></a><a class="card" href="#requests"><h3>Заявки ↗</h3><p>Планування та узгодження з компаніями.</p></a></div>`:`<div class="card table-scroll"><table><tr><th>ID</th><th>${master?'Спеціалізація':'Компанія'}</th><th>Джерело</th><th>Документи</th><th>Статус</th><th>Дії</th></tr>${(master?workers.slice(0,4):[{id:201,job:'Bouwbedrijf Parkzicht B.V.'},{id:202,job:'Voorbeeld Renovatie B.V.'},{id:203,job:'Projectbouw Noord B.V.'}]).map(w=>`<tr><td>#${w.id}</td><td>${w.job}</td><td>${master?'Ukrwerkspot':'UHR'}</td><td><button class="btn light" data-toast="Перегляд: документи на перевірці.">Переглянути</button></td><td><span class="badge ${state.approved.has(w.id)?'':'yellow'}">${state.approved.has(w.id)?'Схвалено':'На перевірці'}</span></td><td><button class="btn" data-approve="${w.id}">Схвалити</button> <button class="btn light" data-toast="запит на оновлення документів підготовлено.">Уточнити</button></td></tr>`).join('')}</table></div><div class="note">${master?'Після реальної перевірки публікується лише професійний профіль без імені та контактів.':'Після перевірки компанія отримає доступ до каталогу. У прототипі авторизація відсутня.'}</div>`}` ,page)}
function render(){const [page='home',arg]=(location.hash.slice(1)||'home').split('/');if(!uk&&!admin&&['overview','catalog','favorites','profile','request','requests','request-detail','messages','company','documents','settings'].includes(page)&&state.account?.company?.status!=='approved'){location.hash=state.account?'register':'login';return}if(admin&&page!=='home')app.innerHTML=adminPage(page);else if(admin)app.innerHTML=adminPage('overview');else if(page==='home')app.innerHTML=landing();else if(page==='register')app.innerHTML=registration();else if(page==='overview')app.innerHTML=overview();else if(page==='catalog'||page==='favorites')app.innerHTML=catalog(page==='favorites',arg);else if(page==='profile')app.innerHTML=profile(arg);else if(page==='request')app.innerHTML=requestForm(arg);else if(page==='requests')app.innerHTML=requestsPage();else if(page==='messages')app.innerHTML=messages(arg);else if(['company','documents','settings'].includes(page))app.innerHTML=account(page);else if(page==='login'||page==='reset')app.innerHTML=login(page==='reset',arg||'');else if(page==='request-detail')app.innerHTML=requestDetail(arg);else app.innerHTML=info(page);filterCards();icons();if(arg&&page==='home')document.getElementById(arg)?.scrollIntoView({behavior:'smooth'});else window.scrollTo(0,0);}
function toast(text){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),4000)}
function saveForm(form){for(const el of form.elements){if(!el.name||el.type==='submit')continue;if(el.type==='file'){if(el.files.length){state.files[el.name]=Array.from(el.files);state.form[el.name]=state.files[el.name].map(f=>f.name).join(', ')}}else state.form[el.name]=el.type==='checkbox'?el.checked:el.value}}
app.addEventListener('click',async e=>{const section=e.target.closest('[data-section]');if(section){e.preventDefault();document.getElementById(section.dataset.section)?.scrollIntoView({behavior:'smooth'});return}const t=e.target.closest('[data-fav],[data-back],[data-toast],[data-filter-toggle],[data-reset],[data-approve],[data-logout]');if(!t)return;if(t.hasAttribute('data-logout')){e.preventDefault();companyApi('auth/logout',{method:'POST'}).catch(()=>{});state.account=null;state.wizard=0;state.sna=null;state.form={};state.files={};requests=[];companyProfile=null;state.favorites=new Set();location.hash='home';render();return}if(t.dataset.fav){const id=Number(t.dataset.fav);try{const data=await companyApi('favorites/'+id,{method:'POST'});state.favorites=new Set(data.ids)}catch(error){toast(error.message);return}const saved=state.favorites.has(id);document.querySelectorAll('[data-fav="'+id+'"]').forEach(btn=>{btn.classList.toggle('saved',saved);btn.setAttribute('aria-pressed',String(saved))});icons();if(location.hash.startsWith('#favorites'))filterCards()}if(t.hasAttribute('data-back')){saveForm(document.querySelector('#wizard'));state.wizard=Math.max(0,state.wizard-1);render()}if(t.dataset.toast)toast(t.dataset.toast);if(t.hasAttribute('data-filter-toggle')){const opened=document.querySelector('.filters').classList.toggle('open');document.querySelectorAll('[data-filter-toggle]').forEach(b=>b.setAttribute('aria-expanded',String(opened)))}if(t.hasAttribute('data-reset')){document.querySelectorAll('.filters select').forEach(s=>s.selectedIndex=0);document.querySelector('#rate').value='';document.querySelector('#search').value='';filterCards()}if(t.dataset.approve){state.approved.add(Number(t.dataset.approve));render();toast('Статус оновлено.')}});
app.addEventListener('input',e=>{if(e.target.closest('.catalog')||e.target.id==='search')filterCards();const blankOptional=!e.target.required&&e.target.value==='';if(e.target.name==='kvk')e.target.setCustomValidity(blankOptional||/^\d{8}$/.test(e.target.value)?'':uk?'KVK має містити 8 цифр':'KVK bestaat uit 8 cijfers');if(e.target.type==='number')e.target.setCustomValidity(blankOptional||Number(e.target.value)>0?'':uk?'Введіть число більше нуля':'Vul een positief getal in');});
app.addEventListener('change',async e=>{if(e.target.type==='file')e.target.parentElement.querySelector('[data-files]').textContent=Array.from(e.target.files).map(f=>f.name).join(', ');if(e.target.name==='sna'&&e.target.files.length){saveForm(e.target.form);state.sna=null;state.form.kvk='';state.snaBusy=true;render();try{await checkSna()}catch(error){toast(error.message)}render();return}if(e.target.id==='request-status'){const value=e.target.value;document.querySelectorAll('tbody tr').forEach(row=>row.hidden=value!=='Alle statussen'&&!row.textContent.includes(value))}if(e.target.classList.contains('language'))toast(uk?'Цей прототип представлено українською. Інші мови буде підключено пізніше.':'De interface is Nederlandstalig. Andere talen volgen later.');});
app.addEventListener('dragover',e=>{if(e.target.closest('[data-drop]'))e.preventDefault()});app.addEventListener('drop',e=>{const drop=e.target.closest('[data-drop]');if(!drop)return;e.preventDefault();const input=drop.querySelector('input');input.files=e.dataTransfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));});
app.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.id==='wizard'&&!uk){await companyStep(f);return}if(f.id==='wizard'){saveForm(f);if(f.dataset.last!=='true'){state.wizard++;render();return}const button=f.querySelector('button:not([type="button"])');button.disabled=true;button.textContent=uk?'Надсилаємо…':'Bezig met verzenden…';try{state.submitted=await submitApplication();render()}catch(error){toast(error.message);button.disabled=false;button.textContent=uk?'Надіслати на перевірку':'Registratie indienen'}}else if(f.id==='login-form'){const data=new FormData(f);try{if(f.dataset.reset==='email'){await companyApi('auth/forgot',{method:'POST',body:JSON.stringify({email:data.get('login_email')})});toast('Als dit e-mailadres bij ons bekend is, ontvangt u een herstellink.');return}if(f.dataset.reset==='password'){if(data.get('password')!==data.get('password_repeat'))throw new Error('De wachtwoorden komen niet overeen.');state.account=await companyApi('auth/reset',{method:'POST',body:JSON.stringify({token:f.dataset.token,password:data.get('password')})})}else{state.account=await companyApi('auth/login',{method:'POST',body:JSON.stringify({email:data.get('login_email'),password:data.get('password')})})}await loadCabinet();location.hash=state.account.company?.status==='approved'?'overview':'register'}catch(error){toast(error.message)}}else if(f.id==='request-form'){const data=new FormData(f),w=workers.find(x=>x.id===Number(f.querySelector('[data-worker]').dataset.worker));const count=Number(data.get('count'));try{const item=await companyApi('requests',{method:'POST',body:JSON.stringify({craftsman_id:w.id,project:data.get('project'),site_address:data.get('site_address')||'',start_date:data.get('start')||null,duration:data.get('duration')||'',schedule:data.get('schedule')||'',workers_count:count>0?count:null,work_description:data.get('work')||'',requirements:data.get('requirements')||''})});requests.unshift(item);location.hash='requests';toast('Aanvraag verstuurd naar uw UHR-manager.')}catch(error){toast(error.message)}}else if(f.id==='chat-form'){try{const item=await companyApi('requests/'+encodeURIComponent(f.dataset.request)+'/messages',{method:'POST',body:JSON.stringify({body:new FormData(f).get('message')})});const row=requests.find(r=>r.id===item.id);if(row)Object.assign(row,item);render()}catch(error){toast(error.message)}}else if(f.id==='account-form'){const data=new FormData(f);try{companyProfile=await companyApi('profile',{method:'PUT',body:JSON.stringify({contact_name:data.get('contact_name'),contact_role:data.get('contact_role')||'',phone:data.get('phone'),website:data.get('website')||'',address:data.get('address')||'',description:data.get('description')||''})});toast('Opgeslagen.');render()}catch(error){toast(error.message)}}else toast(uk?'Дані не надсилаються.':'Wijzigingen zijn niet verzonden.');});
window.addEventListener('hashchange',render);render();



